import { seededRandom } from '#lib/baby/random.ts';
import { scriptPack } from '#lib/library/pack.ts';
import { Doctor } from './doctor.ts';
import { patientLines } from './patient.ts';

/**
 * 600 one-exchange conversations with ELIZA, its replies generated by the DOCTOR script.
 * The seed fixes the pack, so it’s the same text on every load and for every Baby.
 */
const EXCHANGES = 600;
const SEED = 1966;

function doctorScript(): string {
	const doctor = new Doctor();
	return patientLines(EXCHANGES, seededRandom(SEED))
		.map((line) => `you: ${line}\nbaby: ${doctor.respond(line)}`)
		.join('\n\n');
}

export const eliza = scriptPack('eliza', 'ELIZA (1966)', doctorScript());
